import sys

class SegTree:
    def __init__(self, n):
        self.n = n
        self.size = 1
        while self.size < n:
            self.size <<= 1
        self.mn = [10**18] * (2 * self.size)
        self.mx = [-10**18] * (2 * self.size)
        self.lazy = [0] * (2 * self.size)

        for i in range(n):
            self.mn[self.size + i] = self.mx[self.size + i] = i + 1
        for i in range(self.size - 1, 0, -1):
            self.mn[i] = min(self.mn[i << 1], self.mn[i << 1 | 1])
            self.mx[i] = max(self.mx[i << 1], self.mx[i << 1 | 1])

    def _apply(self, idx, val):
        self.mn[idx] += val
        self.mx[idx] += val
        self.lazy[idx] += val

    def _push(self, idx):
        if self.lazy[idx]:
            v = self.lazy[idx]
            self._apply(idx << 1, v)
            self._apply(idx << 1 | 1, v)
            self.lazy[idx] = 0

    def range_add(self, left, right, val, idx=1, nl=0, nr=None):
        if nr is None:
            nr = self.size
        if right <= nl or nr <= left:
            return
        if left <= nl and nr <= right:
            self._apply(idx, val)
            return
        self._push(idx)
        mid = (nl + nr) >> 1
        self.range_add(left, right, val, idx << 1, nl, mid)
        self.range_add(left, right, val, idx << 1 | 1, mid, nr)
        self.mn[idx] = min(self.mn[idx << 1], self.mn[idx << 1 | 1])
        self.mx[idx] = max(self.mx[idx << 1], self.mx[idx << 1 | 1])

    def first_ge(self, x):
        if self.mx[1] < x:
            return self.n
        idx, nl, nr = 1, 0, self.size
        while idx < self.size:
            self._push(idx)
            mid = (nl + nr) >> 1
            if self.mx[idx << 1] >= x:
                idx = idx << 1
                nr = mid
            else:
                idx = idx << 1 | 1
                nl = mid
        return min(nl, self.n)

    def first_gt(self, x):
        if self.mx[1] <= x:
            return self.n
        idx, nl, nr = 1, 0, self.size
        while idx < self.size:
            self._push(idx)
            mid = (nl + nr) >> 1
            if self.mx[idx << 1] > x:
                idx = idx << 1
                nr = mid
            else:
                idx = idx << 1 | 1
                nl = mid
        return min(nl, self.n)

    def point_get(self, pos):
        idx, nl, nr = 1, 0, self.size
        while idx < self.size:
            self._push(idx)
            mid = (nl + nr) >> 1
            if pos < mid:
                idx = idx << 1
                nr = mid
            else:
                idx = idx << 1 | 1
                nl = mid
        return self.mn[idx]


def main():
    input = sys.stdin.readline
    N = int(input())
    contests = [tuple(map(int, input().split())) for _ in range(N)]

    MAX_X = 500000
    seg = SegTree(MAX_X)

    for l, r in contests:
        left = seg.first_ge(l)
        right = seg.first_gt(r)
        if left < right:
            seg.range_add(left, right, 1)

    Q = int(input())
    ans = []
    for _ in range(Q):
        x = int(input())
        ans.append(str(seg.point_get(x - 1)))

    print("\n".join(ans))


if __name__ == "__main__":
